-- =============================================================================
-- MCP Search - bulk sample data (200 generated product rows)
-- =============================================================================
-- Adds 200 varied products to the existing `products` table. Titles/bodies are
-- generated from a mix of adjectives, product types, and categories so the text
-- is diverse enough for hybrid search to be interesting. embedding is left NULL
-- on every row - run the batched backfill afterward to populate them.
--
-- Run with:  mysql -u root -p mydb < add-200-products.sql
-- or paste into your SQL client with `mydb` selected.
-- =============================================================================

USE mydb;


SELECT COUNT(*) AS total_rows FROM products;
SELECT COUNT(*) AS rows_missing_embedding FROM products WHERE embedding IS NULL;
